function isPrime(n){ n=BigInt(n); if(n<2n) return false; if(n<4n) return true; if(n%2n===0n) return false; for(var i=3n;i*i<=n;i+=2n){ if(n%i===0n) return false; } return true; }
function primeFactors(n){ n=BigInt(n); if(n<2n) return {}; var f={}, x=n; if(x<0n) x=-x; while(x%2n===0n){ f[2]=(f[2]||0n)+1n; x/=2n; } for(var i=3n;i*i<=x;i+=2n){ while(x%i===0n){ f[i.toString()]=((f[i.toString()]||0n)+1n); x/=i; } } if(x>1n) f[x.toString()]=(f[x.toString()]||0n)+1n; return f; }
function factorString(n){ var f=primeFactors(n); if(n===0n||n===1n||n===-1n) return n.toString(); var keys=Object.keys(f).map(BigInt).sort(function(a,b){return a<b?-1:1;}); var neg=n<0n?"-":""; return neg+keys.map(function(p){ var e=f[p.toString()]; return e===1n? p.toString() : p.toString()+"^"+e.toString(); }).join(" * "); }
var EXPORTS = { isPrime:isPrime, primeFactors:primeFactors, factorString:factorString };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PrimeFactorForgePure = EXPORTS; }
